import { mkdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";

const COMMAND_TYPES_VERSION = 1;

const COMMAND_TYPES_D_TS = `/**
 * AUTO-GENERATED by letters — do not edit or delete.
 * Ambient types for custom commands in this folder.
 * Version: ${COMMAND_TYPES_VERSION}
 */
declare global {
  type SandboxMode = "read-only" | "workspace-write" | "danger-full-access";
  type ThinkingLevel = "off" | "minimal" | "low" | "medium" | "high" | "xhigh" | "max";

  interface ContextSnapshot {
    used: number;
    projectedTokens?: number;
    window: number;
    percent: number;
    breakdown: { systemTokens: number; toolsTokens: number; messageTokens: number } | null;
    lastTurn?: {
      input: number;
      output: number;
      cacheRead: number;
      cacheWrite: number;
      totalTokens: number;
      reasoning?: number;
      cost?: unknown;
    };
    workspace: string | null;
    storage: string | null;
    model: string | null;
    sandboxMode: SandboxMode;
  }

  interface ReadonlyContext {
    readonly turn: number;
    readonly running: boolean;
    readonly lastVisibleAt: number;
    readonly lastTurnEndAt: number;
    readonly storage_path: string | null;
    readonly workspace_path: string | null;
    readonly sandbox_mode: SandboxMode;
    readonly model: { provider: string; modelId?: string } | null;
    readonly thinkingLevel: ThinkingLevel;
    composeSystemPrompt(): string;
    visibleElapsedMs(): number;
  }

  interface CommandUtils {
    prompt(text: string): Promise<{ ok: boolean; error?: string }>;
    snapshot(): Promise<ContextSnapshot>;
    sendMessage(text: string): Promise<void>;
  }

  interface CommandContext {
    partner: string;
    dir: string;
  }

  interface CommandInvocation {
    commandId: string;
    ctx: CommandContext;
    rawInput: string;
    signal: AbortSignal;
    context: ReadonlyContext;
    utils: CommandUtils;
  }

  interface CommandResult {
    kind: "success" | "error";
    text?: string;
  }

  interface CommandDefinition {
    description: string;
    kind?: "execute" | "leadingInput";
    hint?: string;
    timeout?: number;
    recordInput?: boolean;
    handler(invocation: CommandInvocation): CommandResult | Promise<CommandResult>;
  }
}

export {};
`;

const TSCONFIG_JSON = `{
  "compilerOptions": {
    "strict": true,
    "module": "ESNext",
    "moduleResolution": "bundler",
    "target": "ESNext",
    "lib": ["ESNext", "DOM"],
    "skipLibCheck": true
  },
  "include": ["**/*.ts"]
}
`;

const EXAMPLE_TS = `// _example.ts — copy this file to <name>.ts and edit.
// Files starting with "_" are ignored by letters, so this template never becomes a command.
const command: CommandDefinition = {
  description: "Describe what this command does", // shown in the / menu
  // kind: optional. With hint it becomes leadingInput (select, then keep typing args).
  hint: "[<args>]",
  // timeout: 30,
  async handler({ context, utils, rawInput }) {
    // context is read-only; mutate the session only through utils.
    const s = await utils.snapshot(); // same context as the UI meter
    const arg = rawInput.trim();
    // To hand off to the model: await utils.prompt("...")
    // Output is not shown from the return value; post it as a visible message instead.
    await utils.sendMessage("arg=" + arg + " used=" + s.used);
    return { kind: "success" };
  },
};

export { command };
`;

const README_MD = `# letters commands

Drop a .ts file here and it becomes a slash command (/<filename>).
Files starting with "_" are ignored (templates).

## Quick start

    const command: CommandDefinition = {
      description: "What this does",
      handler: async ({ utils }) => {
        const s = await utils.snapshot();
        await utils.sendMessage("used " + s.used);
        return { kind: "success" };
      },
    };
    export { command };

Copy _example.ts to your-command.ts and edit.

## Contract

- description — shown in the / menu (required).
- kind — optional; with hint it becomes leadingInput, otherwise execute.
- handler({ context, utils, rawInput, signal }) — context is read-only; mutate only through utils.
- utils.snapshot() — same context as the UI meter.
- utils.prompt(text) — inject a user message and wait for the agent turn.
- utils.sendMessage(text) — post a visible [to user] message.
- Return { kind: "success" | "error" } — output is not rendered from the return value; use utils.sendMessage to show it.

Full types live in command-types.d.ts.
`;

const SCAFFOLD_FILES = [
	{ name: "command-types.d.ts", content: COMMAND_TYPES_D_TS },
	{ name: "tsconfig.json", content: TSCONFIG_JSON },
	{ name: "_example.ts", content: EXAMPLE_TS },
	{ name: "README.md", content: README_MD },
];

export async function scaffoldCommandsDir(dir: string): Promise<void> {
	await mkdir(dir, { recursive: true });
	for (const file of SCAFFOLD_FILES) {
		const path = join(dir, file.name);
		try {
			await readFile(path);
		} catch {
			await writeFile(path, file.content);
		}
	}
}
